using System.Text.Json;
using McpServerManager.UI.Core.Services;

/// <summary>Compares Dispose cancellation ordering with a synchronous cancellation-aware callback.</summary>
internal static class Program
{
    /// <summary>Runs the same probe against both independently implemented timer services.</summary>
    private static void Main()
    {
        Probe("Core", new McpServerManager.Core.Services.Infrastructure.TimerService());
        Probe("UI.Core", new McpServerManager.UI.Core.Services.Infrastructure.TimerService());
    }

    /// <summary>Uses explicit entry signals and an external rescue to avoid leaving a blocked worker behind.</summary>
    private static void Probe(string name, ITimerService service)
    {
        using var entered = new ManualResetEventSlim();
        using var disposing = new ManualResetEventSlim();
        using var finished = new ManualResetEventSlim();
        using var rescue = new ManualResetEventSlim();
        CancellationToken callbackToken = default;
        var handle = service.CreateOneShot(TimeSpan.FromMilliseconds(1), ct =>
        {
            callbackToken = ct;
            entered.Set();
            WaitHandle.WaitAny(new[] { ct.WaitHandle, rescue.WaitHandle });
            return Task.CompletedTask;
        });
        if (!entered.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("callback entry");
        var worker = Task.Factory.StartNew(() =>
        {
            disposing.Set();
            handle.Dispose();
            finished.Set();
        }, CancellationToken.None, TaskCreationOptions.LongRunning, TaskScheduler.Default);
        if (!disposing.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("Dispose entry");
        bool completedWithoutRescue = finished.Wait(TimeSpan.FromSeconds(2));
        bool canceledBeforeRescue = callbackToken.IsCancellationRequested;
        rescue.Set();
        if (!finished.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("Dispose after rescue");
        worker.GetAwaiter().GetResult();
        Console.WriteLine(JsonSerializer.Serialize(new { service = name, completedWithoutRescue, canceledBeforeRescue, completedAfterRescue = finished.IsSet, requiredExternalRelease = !completedWithoutRescue }));
    }
}

