$ErrorActionPreference='Stop'
$final=@()
foreach($r in $script:inventory){
 $p=gh pr view $r.pr.number --repo "sharpninja/$($r.repo)" --json number,url,state,isDraft,mergedAt,headRefOid
 if($LASTEXITCODE -ne 0){throw 'Final PR read failed'}
 $j=$p|ConvertFrom-Json
 $final += [pscustomobject]@{repo=$r.repo;number=$j.number;url=$j.url;state=$j.state;draft=$j.isDraft;mergedAt=$j.mergedAt;head=$j.headRefOid;expected=$r.tip;match=($j.headRefOid -eq $r.tip -and $j.state -eq 'OPEN' -and $j.isDraft -and !$j.mergedAt);utc=[DateTime]::UtcNow.ToString('o')}
}
$final|ConvertTo-Json -Depth 6 > (Join-Path $script:ev 'final-pr-state.json')
$final|Select-Object repo,match,head|ConvertTo-Json -Compress
if(@($final|Where-Object {!$_.match}).Count){throw 'PR gate failed'}
$tools=$script:inventory|Where-Object repo -eq 'McpServerTools'
$static=@()
foreach($f in Get-ChildItem $tools.snapshot -Filter '*.json'){
 $errorText=$null
 try {
  $j=Get-Content $f.FullName -Raw|ConvertFrom-Json -AsHashtable
  $schema=$j.parameterSchema|ConvertFrom-Json -AsHashtable
  if($schema.type -ne 'object' -or !$j.name -or !$j.description -or !$j.commandTemplate){throw 'Missing manifest field or object schema'}
  foreach($required in $schema.required){if(!$schema.properties.ContainsKey($required)){throw "Undeclared required property $required"}}
 } catch { $errorText=$_.Exception.Message }
 $static += [pscustomobject]@{file=$f.Name;isPlugin=$f.Name -like '*-plugin.json';passed=($null -eq $errorText);error=$errorText}
}
$static|ConvertTo-Json -Depth 6 > (Join-Path $script:ev 'all-tools-static.json')
$static|Group-Object isPlugin|ForEach-Object {"Tools static plugin=$($_.Name) total=$($_.Count) passed=$(@($_.Group|Where-Object passed).Count) failed=$(@($_.Group|Where-Object {!$_.passed}).Count)"}
$probe=@()
