const fs = require('fs'), path = require('path'), vm = require('vm'), assert = require('assert/strict');
const {EventEmitter} = require('events');
(async () => {
 let total=0;
 for (const root of process.argv.slice(2)) {
  const source = fs.readFileSync(path.join(root,'package/dist/transport/repl-bridge.js'),'utf8');
  for(const platform of ['win32','linux']) {
   const p = platform==='win32'?path.win32:path.posix;
   const dir = platform==='win32'?'C:\\tools':'/tools';
   const suffix = platform==='win32'?'.exe':'';
   const cases = [
    {name:'new-only',files:['qbrain-ai-repl'+suffix],want:'qbrain-ai-repl'},
    {name:'legacy-only',files:['mcpserver-repl'+suffix],want:'mcpserver-repl'},
    {name:'both-prefer-new',files:['mcpserver-repl'+suffix,'qbrain-ai-repl'+suffix],want:'qbrain-ai-repl'},
    {name:'neither-default-new',files:[],want:'qbrain-ai-repl'},
    {name:'command-override',files:['qbrain-ai-repl'+suffix],env:{MCPSERVER_REPL_COMMAND:'custom-repl'},want:'custom-repl'},
    {name:'bin-override-precedence',files:['qbrain-ai-repl'+suffix],env:{MCPSERVER_REPL_BIN:'custom-bin',MCPSERVER_REPL_COMMAND:'custom-command'},want:'custom-bin'}
   ];
   if(platform==='win32') cases.push(
    {name:'new-cmd',files:['qbrain-ai-repl.cmd'],want:'qbrain-ai-repl'},
    {name:'legacy-cmd',files:['mcpserver-repl.cmd'],want:'mcpserver-repl'},
    {name:'both-cmd',files:['mcpserver-repl.cmd','qbrain-ai-repl.cmd'],want:'qbrain-ai-repl'}
   );
   for(const test of cases) {
    const calls=[];
    const env={PATH:dir,PLUGIN_AGENT_NAME:'Codex',...test.env};
    const mod={exports:{}};
    const mocks={
     child_process:{spawn:(cmd,args,opts)=>{calls.push({cmd,args,opts}); const proc=new EventEmitter(); proc.stdout=new EventEmitter(); proc.stderr=new EventEmitter(); proc.exitCode=null;proc.killed=false;return proc;}},
     fs:{existsSync:file=>test.files.some(f=>p.join(dir,f)===file),statSync:()=>({isDirectory:()=>false})},
     path:p,readline:{createInterface:()=>new EventEmitter()},'js-yaml':{}
    };
    vm.runInNewContext(source,{exports:mod.exports,module:mod,require:name=>{assert(name in mocks,name);return mocks[name];},process:{env,platform,cwd:()=>root,stderr:{write:()=>{}}},setTimeout,clearTimeout,console},{filename:path.join(root,'repl-bridge.js')});
    assert.equal(mod.exports.resolveReplCommand(),test.want);
    await new mod.exports.ReplBridge().ensure();
    assert.equal(calls.length,1);
    assert.equal(calls[0].cmd,test.want);
    assert.deepEqual(Array.from(calls[0].args),['--agent-stdio','--agent','Codex']);
    assert.equal(calls[0].opts.cwd,root);
    total++;
    console.log(JSON.stringify({bundle:path.basename(root),platform,case:test.name,selected:calls[0].cmd,pass:true}));
   }
  }
 }
 console.log(JSON.stringify({total,passed:total,failed:0}));
})().catch(error=>{console.error(error);process.exitCode=1;});
